CREATE FUNCTION "nightscout_migration_namespace".clinical_storage_size() RETURNS trigger LANGUAGE plpgsql SECURITY INVOKER SET search_path=pg_catalog AS $clinical_size$
DECLARE measured bigint;
BEGIN
  SELECT pg_column_size(doc) INTO STRICT measured FROM "nightscout_migration_namespace"."entries" WHERE tenant_id=NEW.tenant_id AND id_kind=NEW.id_kind AND "_id"=NEW."_id";
  UPDATE "nightscout_migration_namespace"."entries" SET storage_bytes=measured WHERE tenant_id=NEW.tenant_id AND id_kind=NEW.id_kind AND "_id"=NEW."_id" AND storage_bytes IS DISTINCT FROM measured;
  RETURN NULL;
END
